+  mkdirSync(origin);
+  mkdirSync(seed);
+  git(origin, "init", "-q", "--bare", "-b", "master");
+  git(seed, "init", "-q", "-b", "master");
+  git(seed, "config", "user.email", "t@example.com");
+  git(seed, "config", "user.name", "T");
