+    const { clone } = makeClone(root);
+    const hang = join(root, "hang.mjs");
+    writeFileSync(hang, "setTimeout(() => {}, 4000);\n");
+    git(clone, "config", "remote.origin.uploadpack", `"${process.execPath.replace(/\\/g, "/")}" "${hang.replace(/\\/g, "/")}"`);
